  "probability": 0.94,
  "range_low": 0.86,
  "range_high": 0.98,
  "summary": [
    "Anchored on historical Mediterranean death rates (~2,100–2,500 per year) and early-2026 pace (about 606 deaths by end-February).",
    "If the March–April pace remains similar, reaching 1,000 deaths by May 2026 is plausible.",
    "Given strong base rates, the posterior probability is high but subject to SAR policy changes and reporting revisions.",
    "Calibration reflects uncertainty due to year-to-year variability and potential data lags."
  ],
  "confidence": "high",
  "narrative": "Early-2026 data indicate a fast pace that, when applied to a high historical baseline of Mediterranean fatalities, yields a high probability of crossing 1,000 deaths by May 2026. The estimate accounts for potential SAR changes and reporting delays, but remains uncertain due to variability in crossing activity.",
  "justification": {
    "anchor": {
      "probability": 0.85,
      "basis": "Reference class is annual Mediterranean deaths recorded by IOM Missing Migrants Project; historical counts around 2,100–2,500 per year (2023–2024) provide a high base-rate anchor. February 2026 pace (~606 by end-Feb) informs an upward update toward 1,000 by May."
    },
    "factor_updates": [
      {
        "factor": "Pace of Mediterranean deaths in early 2026",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "606 deaths by end of February; if March–April maintain or exceed this pace, 1,000+ by May becomes plausible."
      },
      {
        "factor": "Historical base-rate for Mediterranean deaths",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Annual toll frequently in the 2,100–2,500 range, supporting reaching 1,000 by May given current tempo."
      },
      {
        "factor": "Weather and storm activity increasing crossing risk",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Early-2026 reports of dangerous seas and storms raise mortality risk, boosting March–April totals."
      },
      {
        "factor": "Search-and-rescue capacity and policy environment",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Stronger SAR or more permissive policies could reduce fatalities, dampening the probability of crossing 1,000 by May."
      },
      {
        "factor": "Data completeness and missing-person reporting uncertainty",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Verifications and missing cases can adjust totals up or down; introduces uncertainty into trajectory."
      }
    ],
    "synthesis_rationale": "Starting from a high base-rate anchor, we update upward for the observed early-2026 pace and favorable seasonal risk, while acknowledging potential downward pressure from SAR policy changes and data revisions. These factors combine to yield a high posterior probability of 0.94, with an uncertainty range reflected in the range_low and range_high."
  }
}

{
  "probability": 0.94,
